   291  static void close_connection_now(h2o_http2_conn_t *conn)
   292  {
   293      h2o_http2_stream_t *stream;
   294
   295      assert(!h2o_timeout_is_linked(&conn->_write.timeout_entry));
   296
   297      kh_foreach_value(conn->streams, stream, { h2o_http2_stream_close(conn, stream); });
   298
   299      assert(conn->num_streams.pull.open == 0);
   300      assert(conn->num_streams.pull.half_closed == 0);
